async function processAll(items, { signal } = {}) {
  const done = [];
  for (const item of items) {
    signal?.throwIfAborted();          // stop between steps
    await new Promise((r) => setTimeout(r, 50));
    done.push(item);
  }
  return done;
}

const ac = new AbortController();
setTimeout(() => ac.abort(), 120);
processAll([1, 2, 3, 4, 5], { signal: ac.signal })
  .catch((e) => console.log('stopped:', e.name));   // stopped: AbortError

