import http from 'node:http';

class HttpError extends Error {
  constructor(status, message) { super(message); this.status = status; }
}

async function readJson(req, limit = 1_000_000) {
  if (!req.headers['content-type']?.includes('application/json')) {
    throw new HttpError(415, 'Content-Type must be application/json');
  }
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new HttpError(413, 'Payload too large');
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw new HttpError(400, 'Invalid JSON');
  }
}

http.createServer(async (req, res) => {
  try {
    if (req.method === 'POST' && req.url === '/users') {
      const { name, email } = await readJson(req);
      if (!name || !email) throw new HttpError(422, 'name and email are required');
      res.writeHead(201, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ id: 1, name, email }));
    }
    throw new HttpError(404, 'Not found');
  } catch (err) {
    res.writeHead(err.status ?? 500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.status ? err.message : 'Internal error' }));
  }
}).listen(3000);

