export const mongooseErrors = (err, req, res, next) => {
  if (err.name === 'ValidationError') return res.status(422).json({ errors: Object.fromEntries(Object.entries(err.errors).map(([k, v]) => [k, v.message])) });
  if (err.name === 'CastError') return res.status(400).json({ error: 'Invalid id' });
  if (err.code === 11000) return res.status(409).json({ error: 'Already exists', fields: Object.keys(err.keyPattern) });
  next(err);
};

