// errors.js
export class AppError extends Error {
  constructor(message, status = 500, code = 'INTERNAL_ERROR', details) {
    super(message);
    Object.assign(this, { name: this.constructor.name, status, code, details, isOperational: true });
  }
}
export class NotFoundError extends AppError {
  constructor(what = 'Resource') { super(`${what} not found`, 404, 'NOT_FOUND'); }
}
export class ValidationError extends AppError {
  constructor(details) { super('Validation failed', 422, 'VALIDATION_ERROR', details); }
}

// errorHandler.js
export function notFound(req, res, next) { next(new NotFoundError('Route')); }

export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err);
  const known = err instanceof AppError;
  const status = known ? err.status : err.type === 'entity.too.large' ? 413 : err.status ?? 500;
  if (status >= 500) req.log?.error({ err }, 'unhandled error');
  res.status(status).json({
    error: {
      code: known ? err.code : 'INTERNAL_ERROR',
      message: status >= 500 && process.env.NODE_ENV === 'production' ? 'Something went wrong' : err.message,
      details: known ? err.details : undefined,
      requestId: req.id,
    },
  });
}

