// pool.mjs - run: node pool.mjs
import { Worker, isMainThread, parentPort } from 'node:worker_threads';

if (isMainThread) {
  class Pool {
    constructor(size = 2) {
      this.idle = [];
      this.queue = [];
      for (let i = 0; i < size; i++) this.idle.push(this.#spawn());
    }
    #spawn() {
      const w = new Worker(new URL(import.meta.url));
      w.on('message', (result) => {
        const { resolve } = w.job;
        w.job = null;
        resolve(result);
        const next = this.queue.shift();
        if (next) this.#run(w, next); else this.idle.push(w);
      });
      w.on('error', (err) => w.job?.reject(err));
      return w;
    }
    #run(w, job) { w.job = job; w.postMessage(job.data); }
    exec(data) {
      return new Promise((resolve, reject) => {
        const job = { data, resolve, reject };
        const w = this.idle.pop();
        if (w) this.#run(w, job); else this.queue.push(job);
      });
    }
    close() { return Promise.all(this.idle.map((w) => w.terminate())); }
  }

  const pool = new Pool(2);
  console.time('4 jobs on 2 workers');
  const results = await Promise.all([35, 35, 35, 35].map((n) => pool.exec(n)));
  console.timeEnd('4 jobs on 2 workers');
  console.log(results);                       // [ 9227465, 9227465, 9227465, 9227465 ]
  await pool.close();
} else {
  const fib = (n) => (n < 2 ? n : fib(n - 1) + fib(n - 2));
  parentPort.on('message', (n) => parentPort.postMessage(fib(n)));
}

