#!/usr/bin/env node
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { styleText } from 'node:util';

const FILE = process.env.TODO_FILE ?? path.join(os.homedir(), '.todos.json');

async function load() {
  try {
    return JSON.parse(await fs.readFile(FILE, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function save(todos) {
  const tmp = `${FILE}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(todos, null, 2));
  await fs.rename(tmp, FILE);              // atomic replace: no half-written file
}

function fail(message) {
  console.error(styleText('red', `Error: ${message}`));
  process.exit(1);
}

const [command, ...args] = process.argv.slice(2);
const todos = await load();

switch (command) {
  case 'add': {
    const title = args.join(' ').trim();
    if (!title) fail('Usage: todo add <text>');
    const id = todos.reduce((max, t) => Math.max(max, t.id), 0) + 1;
    todos.push({ id, title, done: false, createdAt: new Date().toISOString() });
    await save(todos);
    console.log(`Added #${id}: ${title}`);
    break;
  }
  case 'list': {
    if (todos.length === 0) { console.log('Nothing to do. Enjoy!'); break; }
    for (const t of todos) {
      const box = t.done ? '[x]' : '[ ]';
      const line = `${String(t.id).padStart(2)} ${box} ${t.title}`;
      console.log(t.done ? styleText('gray', line) : line);
    }
    const open = todos.filter((t) => !t.done).length;
    console.log(`\n${open} open, ${todos.length - open} done`);
    break;
  }
  case 'done': {
    const todo = todos.find((t) => t.id === Number(args[0]));
    if (!todo) fail(`No todo with id ${args[0]}`);
    todo.done = true;
    await save(todos);
    console.log(`Completed #${todo.id}`);
    break;
  }
  case 'remove': {
    const index = todos.findIndex((t) => t.id === Number(args[0]));
    if (index === -1) fail(`No todo with id ${args[0]}`);
    const [removed] = todos.splice(index, 1);
    await save(todos);
    console.log(`Removed #${removed.id}`);
    break;
  }
  case 'clear': {
    await save(todos.filter((t) => !t.done));
    console.log('Cleared completed todos');
    break;
  }
  default:
    console.log('Usage: todo <add|list|done|remove|clear> [args]');
    process.exitCode = command ? 1 : 0;
}

