import fs from 'node:fs/promises';
import path from 'node:path';
import { parseArgs } from 'node:util';

const CATEGORIES = {
  Images:    ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.svg'],
  Documents: ['.pdf', '.doc', '.docx', '.txt', '.md', '.xlsx', '.pptx'],
  Videos:    ['.mp4', '.mkv', '.mov', '.avi'],
  Audio:     ['.mp3', '.wav', '.flac'],
  Archives:  ['.zip', '.tar', '.gz', '.rar', '.7z'],
  Code:      ['.js', '.ts', '.json', '.html', '.css', '.py'],
};

const categoryOf = (file) => {
  const ext = path.extname(file).toLowerCase();
  const found = Object.entries(CATEGORIES).find(([, exts]) => exts.includes(ext));
  return found ? found[0] : 'Other';
};

async function exists(p) {
  try { await fs.access(p); return true; } catch { return false; }
}

// report.pdf -> report (1).pdf when the name is taken
async function uniquePath(target) {
  const { dir, name, ext } = path.parse(target);
  let candidate = target;
  for (let n = 1; await exists(candidate); n++) {
    candidate = path.join(dir, `${name} (${n})${ext}`);
  }
  return candidate;
}

const { values, positionals } = parseArgs({
  allowPositionals: true,
  options: { 'dry-run': { type: 'boolean', short: 'n' } },
});

const root = path.resolve(positionals[0] ?? '.');
const dryRun = values['dry-run'];
const summary = {};

for (const entry of await fs.readdir(root, { withFileTypes: true })) {
  if (!entry.isFile() || entry.name.startsWith('.')) continue;   // skip folders and dotfiles

  const category = categoryOf(entry.name);
  const from = path.join(root, entry.name);
  const folder = path.join(root, category);
  const to = await uniquePath(path.join(folder, entry.name));

  console.log(`${dryRun ? '[dry-run] ' : ''}${entry.name}  ->  ${category}/${path.basename(to)}`);
  if (!dryRun) {
    await fs.mkdir(folder, { recursive: true });
    await fs.rename(from, to);
  }
  summary[category] = (summary[category] ?? 0) + 1;
}

console.table(summary);

