const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

function page(visits) {
  const items = messages
    .map((m) => `<li><strong>${escapeHtml(m.name)}</strong>: ${escapeHtml(m.text)} <small>${m.at}</small></li>`)
    .join('\n') || '<li><em>No messages yet</em></li>';

