function parseCookies(header = '') {
  return Object.fromEntries(header.split(';').map((p) => p.trim().split('=')).filter(([k]) => k));
}

async function readForm(req, limit = 10_000) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw Object.assign(new Error('Too large'), { status: 413 });
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString()));
}

const server = http.createServer(async (req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');
  try {
    if (req.method === 'GET' && pathname === '/') {
      const visits = Number(parseCookies(req.headers.cookie).visits ?? 0) + 1;
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Set-Cookie': `visits=${visits}; Max-Age=31536000; HttpOnly; SameSite=Lax; Path=/`,
      });
      return res.end(page(visits));
    }

    if (req.method === 'POST' && pathname === '/sign') {
      const { name = '', text = '' } = await readForm(req);
      if (!name.trim() || !text.trim()) {
        res.writeHead(400, { 'Content-Type': 'text/plain' });
        return res.end('Name and message are required');
      }
      messages.unshift({ name: name.trim(), text: text.trim(), at: new Date().toLocaleTimeString() });
      res.writeHead(303, { Location: '/' });          // Post/Redirect/Get: refresh will not resubmit
      return res.end();
    }

    if (pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      return res.end('ok');
    }

    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not found');
  } catch (err) {
    res.writeHead(err.status ?? 500, { 'Content-Type': 'text/plain' });
    res.end(err.status ? err.message : 'Server error');
  }
});

