// ---- server.js ----
import http from 'node:http';
import crypto from 'node:crypto';
import fs from 'node:fs/promises';

const PORT = process.env.PORT ?? 3000;
const BASE = process.env.BASE_URL ?? `http://localhost:${PORT}`;
const DB_FILE = process.env.DB_FILE ?? 'links.json';

// ---- storage: a Map persisted to a JSON file ----
const links = new Map();
try {
  for (const [code, link] of Object.entries(JSON.parse(await fs.readFile(DB_FILE, 'utf8')))) links.set(code, link);
} catch (err) {
  if (err.code !== 'ENOENT') throw err;
}

let saving = Promise.resolve();
function persist() {
  saving = saving.then(async () => {
    const tmp = `${DB_FILE}.tmp`;
    await fs.writeFile(tmp, JSON.stringify(Object.fromEntries(links)));
    await fs.rename(tmp, DB_FILE);
  });
  return saving;
}

// ---- core logic ----
function newCode() {
  for (;;) {
    const code = crypto.randomBytes(5).toString('base64url').slice(0, 7);
    if (!links.has(code)) return code;
  }
}

function validateUrl(input) {
  let url;
  try { url = new URL(input); } catch { return null; }
  return ['http:', 'https:'].includes(url.protocol) ? url.href : null;   // block javascript: and file:
}

const json = (res, status, data) => {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
};

async function readJson(req, limit = 10_000) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    if ((size += chunk.length) > limit) throw Object.assign(new Error('Payload too large'), { status: 413 });
    chunks.push(chunk);
  }
  try { return JSON.parse(Buffer.concat(chunks).toString() || '{}'); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

const server = http.createServer(async (req, res) => {
  const { pathname } = new URL(req.url, BASE);
  try {
    if (req.method === 'POST' && pathname === '/shorten') {
      const { url } = await readJson(req);
      const target = validateUrl(url);
      if (!target) return json(res, 422, { error: 'A valid http(s) url is required' });

      const code = newCode();
      links.set(code, { url: target, hits: 0, createdAt: new Date().toISOString() });
      await persist();
      return json(res, 201, { code, short: `${BASE}/${code}`, url: target });
    }

    const stats = pathname.match(/^\/api\/stats\/([\w-]{7})$/);
    if (req.method === 'GET' && stats) {
      const link = links.get(stats[1]);
      return link ? json(res, 200, link) : json(res, 404, { error: 'Unknown code' });
    }

    const redirect = pathname.match(/^\/([\w-]{7})$/);
    if (req.method === 'GET' && redirect) {
      const link = links.get(redirect[1]);
      if (!link) return json(res, 404, { error: 'Unknown code' });
      link.hits++;
      persist();                                      // fire and forget is fine for a counter
      res.writeHead(302, { Location: link.url });
      return res.end();
    }

    json(res, 404, { error: 'Not found' });
  } catch (err) {
    json(res, err.status ?? 500, { error: err.status ? err.message : 'Internal error' });
  }
});

server.listen(PORT, () => console.log(`Shortener ready at ${BASE}`));

