// ---- server.js ----
import http from 'node:http';
import fs from 'node:fs/promises';
import path from 'node:path';
import { WebSocketServer, WebSocket } from 'ws';

const PORT = process.env.PORT ?? 3000;
const indexHtml = await fs.readFile(path.join(import.meta.dirname, 'public', 'index.html'));

const server = http.createServer((req, res) => {
  if (req.url === '/') {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return res.end(indexHtml);
  }
  res.writeHead(404).end('Not found');
});

const wss = new WebSocketServer({ server, maxPayload: 4 * 1024 });   // reject giant frames
const users = new Map();                                              // socket -> nickname

function broadcast(message) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) client.send(data);
  }
}

const sendUsers = () => broadcast({ type: 'users', users: [...users.values()].sort() });

wss.on('connection', (socket) => {
  socket.isAlive = true;
  socket.on('pong', () => { socket.isAlive = true; });

  socket.on('message', (raw) => {
    let msg;
    try { msg = JSON.parse(raw.toString()); } catch { return; }       // ignore garbage

    if (msg.type === 'join') {
      const nick = String(msg.nick ?? '').trim().slice(0, 20) || 'guest';
      if ([...users.values()].includes(nick)) {
        return socket.send(JSON.stringify({ type: 'error', text: `"${nick}" is taken` }));
      }
      users.set(socket, nick);
      broadcast({ type: 'system', text: `${nick} joined` });
      sendUsers();
    } else if (msg.type === 'chat' && users.has(socket)) {
      const text = String(msg.text ?? '').trim().slice(0, 500);
      if (text) broadcast({ type: 'chat', from: users.get(socket), text, at: Date.now() });
    }
  });

  socket.on('close', () => {
    const nick = users.get(socket);
    if (nick) {
      users.delete(socket);
      broadcast({ type: 'system', text: `${nick} left` });
      sendUsers();
    }
  });
});

// heartbeat: drop dead connections
const heartbeat = setInterval(() => {
  for (const socket of wss.clients) {
    if (!socket.isAlive) { socket.terminate(); continue; }
    socket.isAlive = false;
    socket.ping();
  }
}, 30_000);
wss.on('close', () => clearInterval(heartbeat));

server.listen(PORT, () => console.log(`Chat on http://localhost:${PORT}`));
process.on('SIGINT', () => { wss.close(); server.close(() => process.exit(0)); });

