import fs from 'node:fs/promises';
import path from 'node:path';

const SRC = path.resolve('content');
const OUT = path.resolve('dist');

const escapeHtml = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---- inline: **bold**, *italic*, `code`, [text](url) ----
function inline(text) {
  const codes = [];
  let out = escapeHtml(text).replace(/`([^`]+)`/g, (_, c) => `\u0000${codes.push(`<code>${c}</code>`) - 1}\u0000`);
  out = out
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>')
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2">$1</a>');
  return out.replace(/\u0000(\d+)\u0000/g, (_, i) => codes[i]);       // restore code spans untouched
}

// ---- blocks: headings, lists, code fences, paragraphs ----
export function markdownToHtml(md) {
  const lines = md.replace(/\r/g, '').split('\n');
  const html = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    if (line.startsWith('```')) {                                      // fenced code block
      const lang = line.slice(3).trim();
      const code = [];
      for (i++; i < lines.length && !lines[i].startsWith('```'); i++) code.push(lines[i]);
      i++;
      html.push(`<pre><code${lang ? ` class="language-${lang}"` : ''}>${escapeHtml(code.join('\n'))}</code></pre>`);
      continue;
    }

    const heading = line.match(/^(#{1,6})\s+(.*)$/);
    if (heading) {
      const level = heading[1].length;
      html.push(`<h${level}>${inline(heading[2])}</h${level}>`);
      i++;
      continue;
    }

    if (/^\s*[-*]\s+/.test(line)) {                                    // unordered list
      const items = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) items.push(`<li>${inline(lines[i++].replace(/^\s*[-*]\s+/, ''))}</li>`);
      html.push(`<ul>\n${items.join('\n')}\n</ul>`);
      continue;
    }

    if (line.trim() === '') { i++; continue; }

    const para = [];                                                   // paragraph: until blank line
    while (i < lines.length && lines[i].trim() !== '' && !/^(#{1,6}\s|```|\s*[-*]\s)/.test(lines[i])) para.push(lines[i++]);
    html.push(`<p>${inline(para.join(' '))}</p>`);
  }
  return html.join('\n');
}

// ---- front matter: --- key: value --- ----
function parseFrontMatter(raw) {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return { meta: {}, body: raw };
  const meta = Object.fromEntries(match[1].split('\n').map((l) => l.split(/:\s*(.*)/s).slice(0, 2)));
  return { meta, body: match[2] };
}

const template = ({ title, body, nav }) => `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>body{font-family:system-ui;max-width:42rem;margin:2rem auto;padding:0 1rem;line-height:1.6}pre{background:#f4f4f4;padding:1rem;overflow:auto}nav a{margin-right:1rem}</style>
</head>
<body>
  <nav>${nav}</nav>
  <main>
${body}
  </main>
</body>
</html>
`;

async function build() {
  await fs.rm(OUT, { recursive: true, force: true });
  await fs.mkdir(OUT, { recursive: true });

  const files = (await fs.readdir(SRC)).filter((f) => f.endsWith('.md')).sort();
  const pages = [];

  for (const file of files) {
    const { meta, body } = parseFrontMatter(await fs.readFile(path.join(SRC, file), 'utf8'));
    const slug = path.basename(file, '.md');
    pages.push({ slug, title: meta.title ?? slug, date: meta.date ?? '', html: markdownToHtml(body) });
  }

  const nav = ['<a href="index.html">Home</a>', ...pages.map((p) => `<a href="${p.slug}.html">${escapeHtml(p.title)}</a>`)].join('');

  for (const page of pages) {
    await fs.writeFile(path.join(OUT, `${page.slug}.html`), template({ title: page.title, body: page.html, nav }));
  }

  const list = pages.map((p) => `<li><a href="${p.slug}.html">${escapeHtml(p.title)}</a> <small>${p.date}</small></li>`).join('\n');
  await fs.writeFile(path.join(OUT, 'index.html'), template({ title: 'Home', body: `<h1>My Site</h1>\n<ul>\n${list}\n</ul>`, nav }));

  console.log(`Built ${pages.length} pages into ${path.relative(process.cwd(), OUT)}/`);
}

if (process.argv[1] === import.meta.filename) await build();

