import crypto from 'node:crypto';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { pipeline } from 'node:stream/promises';
import express from 'express';
import busboy from 'busboy';

const PORT = process.env.PORT ?? 3000;
const UPLOAD_DIR = path.resolve(process.env.UPLOAD_DIR ?? 'uploads');
const MAX_BYTES = 2 * 1024 * 1024; // 2 MB per file
const ALLOWED = new Map([
  ['image/png', '.png'],
  ['image/jpeg', '.jpg'],
  ['application/pdf', '.pdf'],
  ['text/plain', '.txt'],
]);

await fsp.mkdir(UPLOAD_DIR, { recursive: true });

const app = express();

app.post('/upload', (req, res, next) => {
  if (!req.is('multipart/form-data')) return res.status(415).json({ error: 'Send multipart/form-data' });

  const saved = [];
  const pending = [];
  let failed = false;

  const bb = busboy({ headers: req.headers, limits: { fileSize: MAX_BYTES, files: 5, fields: 10 } });

  const fail = (status, message) => {
    if (failed) return;
    failed = true;
    res.set('Connection', 'close'); // we stop reading the body, so do not reuse this socket
    res.status(status).json({ error: message });
    req.unpipe(bb);
    for (const file of saved) fsp.rm(path.join(UPLOAD_DIR, file.name), { force: true }); // clean partial uploads
  };

  bb.on('file', (field, stream, info) => {
    const ext = ALLOWED.get(info.mimeType);
    if (!ext) {
      stream.resume(); // discard the data
      return fail(415, `File type ${info.mimeType} is not allowed`);
    }

    const name = `${crypto.randomUUID()}${ext}`; // never trust the original file name
    const target = path.join(UPLOAD_DIR, name);
    const entry = { name, original: path.basename(info.filename), type: info.mimeType, size: 0 };
    saved.push(entry);

    stream.on('data', (chunk) => { entry.size += chunk.length; });
    stream.on('limit', () => {
      stream.unpipe();
      fail(413, `File too large (max ${MAX_BYTES / 1024 / 1024} MB)`);
    });

    // stream straight to disk: memory stays flat for any file size
    pending.push(pipeline(stream, fs.createWriteStream(target)).catch(() => {}));
  });

  bb.on('error', next);
  bb.on('close', async () => {
    await Promise.all(pending);
    if (failed) return;
    if (saved.length === 0) return res.status(400).json({ error: 'No file received' });
    res.status(201).json({ files: saved.map((f) => ({ ...f, url: `/files/${f.name}` })) });
  });

  req.pipe(bb);
});

app.get('/files', async (req, res) => {
  const names = await fsp.readdir(UPLOAD_DIR);
  res.json(names.map((name) => ({ name, url: `/files/${name}` })));
});

app.get('/files/:name', (req, res) => {
  const name = path.basename(req.params.name); // blocks ../ tricks
  res.sendFile(path.join(UPLOAD_DIR, name), (err) => {
    if (err && !res.headersSent) res.status(404).json({ error: 'Not found' });
  });
});

app.delete('/files/:name', async (req, res) => {
  await fsp.rm(path.join(UPLOAD_DIR, path.basename(req.params.name)), { force: true });
  res.status(204).end();
});

app.use((err, req, res, next) => {
  console.error(err);
  if (!res.headersSent) res.status(500).json({ error: 'Upload failed' });
});

app.listen(PORT, () => console.log(`Upload service on http://localhost:${PORT} -> ${UPLOAD_DIR}`));

