// parallel.mjs
const a = () => new Promise((res) => setTimeout(() => res('a'), 30));
const b = () => new Promise((res) => setTimeout(() => res('b'), 10));

console.time('seq');  await a(); await b();                       console.timeEnd('seq');  // ~40ms
console.time('par');  console.log(await Promise.all([a(), b()])); console.timeEnd('par');  // [ 'a', 'b' ] ~30ms
